def clumsy_factorial(n):
 stack=[n];op=0
 for value in range(n-1,0,-1):
  if op%4==0:stack[-1]*=value
  elif op%4==1:stack[-1]=int(stack[-1]/value)
  elif op%4==2:stack.append(value)
  else:stack.append(-value)
  op+=1
 return sum(stack)

